const items = $input.all().map(({ json }) => {
  const baseline = /remote|remoto/i.test(json.ubicacion);
  const elegible = /^(colombia only|open worldwide)$/i.test(json.elegibilidad.trim());
  return { json: { ...json, baseline: Number(baseline), mejorado: Number(elegible) } };
});
const metricas = {};
for (const regla of ['baseline', 'mejorado']) {
  const tp = items.filter(x => x.json[regla] === 1 && x.json.clase_real === 1).length;
  const fp = items.filter(x => x.json[regla] === 1 && x.json.clase_real === 0).length;
  const fn = items.filter(x => x.json[regla] === 0 && x.json.clase_real === 1).length;
  const tn = items.filter(x => x.json[regla] === 0 && x.json.clase_real === 0).length;
  metricas[regla] = { tp, fp, fn, tn, precision: tp / (tp + fp), recall: tp / (tp + fn), exactitud: (tp + tn) / items.length };
}
return [{ json: { muestra: items.map(x => x.json), metricas } }];
